import { DOCUMENT_KINDS, expect, expectStatus, test } from "../../fixtures";

test("Approving every extraction approves the vendor", { tag: "@REV-05" }, async ({ apiAs, factory }) => {
  // Arrange
  const reviewer = await apiAs("reviewer");
  const { vendor, extractions } = await factory.vendorInReview();

  // Act
  for (const kind of DOCUMENT_KINDS) {
    await expectStatus(
      await reviewer.post(`/api/extractions/${extractions[kind].id}/decision`, { data: { decision: "approve" } }),
      200,
    );
  }

  // Assert
  // The scenario states these outcomes, so they are checked here even though PW-0 defers them to the backend suite.
  const stored = await expectStatus<{ status: string }>(await reviewer.get(`/api/vendors/${vendor.id}`), 200);
  expect(stored.status).toBe("approved");
  await expect
    .poll(
      async () => {
        const audit = await expectStatus<{ items: { action: string }[] }>(
          await reviewer.get(`/api/vendors/${vendor.id}/audit`),
          200,
        );
        return audit.items.map((e) => e.action);
      },
      { message: "a vendor.approved audit event is recorded" },
    )
    .toContain("vendor.approved");
});
